import{z}from"zod";
const url=z.string().url(),positive=z.coerce.number().positive();
const schema=z.object({DATABASE_URL:z.string().min(1),NEXTAUTH_SECRET:z.string().min(1),NEXTAUTH_URL:url,PRIVATE_STORAGE_ROOT:z.string().min(1),MAX_PREVIEW_UPLOAD_MB:positive,MAX_FINAL_UPLOAD_MB:positive,EMAIL_PROVIDER:z.enum(["console"]).default("console"),EMAIL_APP_BASE_URL:url,WHATSAPP_PROVIDER:z.enum(["console","meta"]).default("console"),WHATSAPP_APP_BASE_URL:url,WHATSAPP_META_ACCESS_TOKEN:z.string().optional(),WHATSAPP_META_PHONE_NUMBER_ID:z.string().optional(),WHATSAPP_META_GRAPH_API_VERSION:z.string().optional(),WHATSAPP_APP_SECRET:z.string().optional(),WHATSAPP_WEBHOOK_VERIFY_TOKEN:z.string().optional(),BACKUP_ROOT:z.string().optional(),BACKUP_RETENTION_DAYS:z.coerce.number().int().positive().default(14),MIN_FREE_DISK_MB:z.coerce.number().nonnegative().optional()}).superRefine((env,ctx)=>{if(env.WHATSAPP_PROVIDER==="meta")for(const key of["WHATSAPP_META_ACCESS_TOKEN","WHATSAPP_META_PHONE_NUMBER_ID","WHATSAPP_META_GRAPH_API_VERSION","WHATSAPP_APP_SECRET","WHATSAPP_WEBHOOK_VERIFY_TOKEN"]as const)if(!env[key])ctx.addIssue({code:"custom",path:[key],message:`${key} requis avec le provider meta`})});
export type ServerEnv=z.infer<typeof schema>;export function validateServerEnv(source:NodeJS.ProcessEnv=process.env){const parsed=schema.safeParse(source);if(!parsed.success)throw new Error(`Configuration serveur invalide: ${parsed.error.issues.map(i=>i.path.join(".")).join(", ")}`);return parsed.data}
